package com.example.devsummit2026.cronet

import org.chromium.net.UploadDataProvider
import org.chromium.net.UploadDataSink
import java.nio.ByteBuffer
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Custom [UploadDataProvider] that continuously streams generated byte chunks,
 * simulating a large file or streaming payload upload to an HTTP/3 test endpoint.
 *
 * @param totalBytes Total bytes to upload (e.g. 50 MB). If -1L, simulates continuous chunked stream.
 * @param chunkSize Size of each chunk delivered in read() calls.
 * @param chunkDelayMs Delay between chunks to simulate realistic network streaming rate,
 *                     giving the user enough time to switch between Wi-Fi and Cellular.
 * @param onBytesTransferred Callback invoked whenever a chunk is written into the sink.
 */
class StreamingUploadDataProvider(
    private val totalBytes: Long = 50L * 1024L * 1024L, // 50 MB
    private val chunkSize: Int = 32 * 1024, // 32 KB chunk
    private val chunkDelayMs: Long = 15L,
    private val onBytesTransferred: (chunkBytes: Long, totalUploadedBytes: Long) -> Unit
) : UploadDataProvider() {

    private var uploadedBytes = 0L
    private val isClosed = AtomicBoolean(false)
    private val dummyPattern = ByteArray(chunkSize) { (it % 256).toByte() }

    override fun getLength(): Long = totalBytes

    override fun read(uploadDataSink: UploadDataSink, byteBuffer: ByteBuffer) {
        if (isClosed.get()) {
            uploadDataSink.onReadError(Exception("Upload streaming was cancelled."))
            return
        }

        // Check if finished
        if (totalBytes > 0 && uploadedBytes >= totalBytes) {
            uploadDataSink.onReadSucceeded(true)
            return
        }

        val remainingCapacity = byteBuffer.remaining()
        val toWrite = if (totalBytes > 0) {
            val remainingBytes = totalBytes - uploadedBytes
            minOf(remainingCapacity.toLong(), remainingBytes, chunkSize.toLong()).toInt()
        } else {
            minOf(remainingCapacity, chunkSize)
        }

        if (toWrite > 0) {
            if (chunkDelayMs > 0) {
                try {
                    Thread.sleep(chunkDelayMs)
                } catch (_: InterruptedException) {
                    if (isClosed.get()) {
                        uploadDataSink.onReadError(Exception("Upload interrupted."))
                        return
                    }
                }
            }

            byteBuffer.put(dummyPattern, 0, toWrite)
            uploadedBytes += toWrite
            onBytesTransferred(toWrite.toLong(), uploadedBytes)

            val endOfStream = totalBytes > 0 && uploadedBytes >= totalBytes
            uploadDataSink.onReadSucceeded(endOfStream)
        } else {
            uploadDataSink.onReadSucceeded(true)
        }
    }

    override fun rewind(uploadDataSink: UploadDataSink) {
        uploadedBytes = 0L
        uploadDataSink.onRewindSucceeded()
    }

    override fun close() {
        isClosed.set(true)
    }
}
